// spec: specs/ssr-seo-public.md (2.2)
// seed: tests/seed.spec.ts
// Прод, только чтение: все URL sitemap, сырой HTML через request API, параллельно по 8.
// og:image объявлений (вес/размер) — в seo-technical/listing-og-image-weight.spec.ts; здесь — картинки остальных страниц.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, metas, canonicals, pool, ORIGIN } from './ssr-seo.helpers';

const DIRTY_PARAM = /^(utm_|from$|source$|fbclid$|gclid$)/i;

test.describe('SSR и SEO публичных страниц — метаданные', () => {
  test('Публичные страницы: meta description, абсолютный canonical без мусорных параметров, og:url = canonical, og:* и og:image 200 image/jpeg #b489db @desktop @prod-safe', async ({ request }) => {
    test.setTimeout(10 * 60_000);
    const sm = await readSitemap(request);
    expect(sm.all.length, 'URL в sitemap').toBeGreaterThan(0);

    const pageImages = new Set<string>();
    const rows = await pool(
      sm.all,
      async (loc) => {
        const u = new URL(loc);
        const problems: string[] = [];
        const { status, html } = await rawHtml(request, u.pathname + u.search);
        if (status !== 200) return { loc, problems: [`HTTP ${status}`] };

        for (const key of ['description', 'og:title', 'og:description', 'og:url', 'og:image']) {
          const v = metas(html, key);
          if (v.length !== 1 || !v[0]) problems.push(`${key}: ${JSON.stringify(v)}`);
        }
        const can = canonicals(html);
        if (can.length !== 1) return { loc, problems: [...problems, `canonical: ${JSON.stringify(can)}`] };
        const c = new URL(can[0], 'http://relative.invalid');
        if (!can[0].startsWith(`${ORIGIN}/`)) problems.push(`canonical не абсолютный ${ORIGIN}: ${can[0]}`);
        const dirty = [...c.searchParams.keys()].filter((k) => DIRTY_PARAM.test(k));
        if (dirty.length) problems.push(`canonical с параметрами ${dirty.join(',')}`);
        if (metas(html, 'og:url')[0] !== can[0]) problems.push(`og:url ${metas(html, 'og:url')[0]} ≠ canonical ${can[0]}`);

        const id = u.pathname === '/businessdetail' ? u.searchParams.get('id') : null;
        const cat = u.pathname === '/search' ? u.searchParams.get('category') : null;
        if (id) {
          if (can[0] !== `${ORIGIN}/businessdetail?id=${id}`) problems.push(`canonical объявления ${can[0]}`);
        } else if (cat) {
          if (c.pathname !== '/search' || c.searchParams.get('category') !== cat || [...c.searchParams.keys()].length !== 1)
            problems.push(`категория не self-canonical: ${can[0]}`);
        } else if (c.href !== u.href) {
          problems.push(`canonical ${can[0]} ≠ ${loc}`);
        }
        const img = metas(html, 'og:image')[0];
        if (!id && img) pageImages.add(img);
        return { loc, problems };
      },
      (loc, e) => ({ loc, problems: [`ошибка запроса: ${e.message.split('\n')[0]}`] }),
    );
    const bad = rows.filter((r) => r.problems.length);
    expect(bad.map((r) => `${r.loc}: ${r.problems.join('; ')}`), `нарушителей ${bad.length}/${rows.length}`).toEqual([]);

    for (const img of pageImages) {
      await test.step(`og:image ${img}`, async () => {
        expect(img, 'og:image абсолютный https').toMatch(/^https:\/\//);
        const res = await request.get(img);
        expect(res.status(), img).toBe(200);
        expect(res.headers()['content-type'] ?? '', img).toContain('image/jpeg');
        expect((await res.body()).length, img).toBeGreaterThan(0);
      });
    }
  });
});
